# plotting.pyimport osimport refrom pathlib import Pathimport matplotlib.pyplot as pltimport numpy as npimport pandas as pdfrom scipy.signal import hilbert, spectrogramfrom sklearn.decomposition import PCAfrom sklearn.preprocessing import StandardScalerfrom shared_feature_utils import (    FS,    NPERSEG,    FREQ_MIN,    bandpass_filter,    compute_psd,    compute_band_energy,)#                                         ********************************************************************#                                                                       統計小工具#                                         ********************************************************************# 這些是純計算工具，和 Step2 主程式的版本相同；只有繪圖時使用def _mad(x):    """以中位數為中心的穩健離散程度（跳過 NaN）"""    x = np.asarray(x, dtype=float)    med = np.nanmedian(x)    return np.nanmedian(np.abs(x - med))def _cohen_d(x1, x0):    """兩組差了幾個標準差：正值 = x1 較大，負值 = x1 較小"""    x1 = np.asarray(x1, dtype=float)    x0 = np.asarray(x0, dtype=float)    x1 = x1[~np.isnan(x1)]    x0 = x0[~np.isnan(x0)]    if len(x1) < 2 or len(x0) < 2:        return np.nan    pooled = np.sqrt((np.std(x1, ddof=1) ** 2 + np.std(x0, ddof=1) ** 2) / 2.0)    if pooled < 1e-12:        return 0.0    return (np.mean(x1) - np.mean(x0)) / pooleddef make_group_name(meta, use_pressure=False):    """把洩漏量、距離（和壓力）組成分組名稱，例如 normal_20cm、leak30_50cm"""    leak_q = int(round(meta["leak_quantity"]))    distance_cm = int(round(meta["distance"] * 100))    leak_tag = "normal" if leak_q == 0 else f"leak{leak_q}"    if use_pressure:        return f"{leak_tag}_{distance_cm}cm_{meta['pressure']:g}bar"    return f"{leak_tag}_{distance_cm}cm"#                                         ********************************************************************#                                                                           視覺化 #                                         ********************************************************************# ==========================# 繪圖的 helper function:自動設定較穩定的y軸範圍# ==========================def _set_robust_ylim(        ax,         series_list,         lower_pct=2,      # 全部資料的第 2 百分位        upper_pct=98,     # 全部資料的第 98 百分位        pad_ratio=0.08):    """    根據多組資料的分位數，自動設定較穩健的 y 軸範圍，避免少數極端值把箱體壓扁。    """    # series_list 裡的每一組資料：轉成 Series -> 去掉 NaN -> 轉成 float -> 再去掉 inf / -inf -> 如果這組還有有效資料，就收進 vals    vals = []    for s in series_list:        arr = np.asarray(pd.Series(s).dropna(), dtype=float)        arr = arr[np.isfinite(arr)]        if arr.size > 0:            vals.append(arr)    # 如果完全沒資料就直接結束    if not vals:        return    # 把所有組合併    all_vals = np.concatenate(vals)    y_low = np.percentile(all_vals, lower_pct)     # 算低分位數    y_high = np.percentile(all_vals, upper_pct)    # 算高分位數    # 如果算出來不是有效數字就結束    if not np.isfinite(y_low) or not np.isfinite(y_high):        return    # 如果上下界一樣，特別處理    if y_low == y_high:        pad = max(abs(y_low) * pad_ratio, 1e-6)        ax.set_ylim(y_low - pad, y_high + pad)        return    # 一般情況下，計算跨度與 padding    span = y_high - y_low                       # span 是主要數據區間的高度    pad = max(span * pad_ratio, 1e-6)           # 再拿 span * pad_ratio 當作上下邊界空間    ax.set_ylim(y_low - pad, y_high + pad)      # 設定 y 軸範圍# ============================================================# 雙通道 ai0, ai1 時頻圖比較(x 軸 = 時間, y 軸 = 頻率)# ============================================================   def plot_record_dual_channel_spectrogram(        record,        save_path=None,        nperseg=8192,       # 做 spectrogram 時，每個小時間窗用多少點來做頻譜分析        noverlap=6144,      # 相鄰兩個小時間窗重疊多少點        fmin=40_000,        fmax=300_000,       # 頻率範圍        cmap="magma",       # 圖配色        diff_cmap="coolwarm",        diff_vlim=5,    ):    """    單一 record 的雙通道時頻圖    x 軸 = time    y 軸 = frequency    color = power(dB)    """    # 從 record 裡拿出 ai0/ai1 訊號，轉成 numpy array，型別是 float    ai0 = np.asarray(record["signal"]["ai0"], dtype=float)    ai1 = np.asarray(record["signal"]["ai1"], dtype=float)    fs = float(record["fs"])     # 取出採樣率 fs，並轉成浮點數    # 對 ai0/ai1 做 spectrogram, 回傳f0-頻率軸, t0-時間軸, S0-功率矩陣    f0, t0, S0 = spectrogram(        ai0, fs=fs, window="hann",        nperseg=nperseg, noverlap=noverlap,        scaling="density", mode="psd"    )    f1, t1, S1 = spectrogram(        ai1, fs=fs, window="hann",        nperseg=nperseg, noverlap=noverlap,        scaling="density", mode="psd"    )    # 頻率遮罩,保留需要的頻段    mask0 = (f0 >= fmin) & (f0 <= fmax)    mask1 = (f1 >= fmin) & (f1 <= fmax)    # 只抓需要的頻段    f0 = f0[mask0]    f1 = f1[mask1]    S0 = S0[mask0, :]    # 把 ai0,ai1 的 spectrogram 功率矩陣在頻率方向一起裁掉    S1 = S1[mask1, :]    # 把 S0,S1,diff 從線性功率轉成 dB 尺度    S0_db = 10 * np.log10(S0 + 1e-12)    S1_db = 10 * np.log10(S1 + 1e-12)    if S0_db.shape != S1_db.shape:        raise ValueError("ai0 and ai1 spectrogram shapes do not match")    diff_db = S1_db - S0_db    # 建立圖畫    fig, axes = plt.subplots(3, 1, figsize=(12, 12), dpi=160, sharex=True)    im0 = axes[0].pcolormesh(t0, f0, S0_db, shading="gouraud", cmap=cmap, vmin=-120, vmax=-100)    axes[0].set_title("ai0 (far) Spectrogram")    axes[0].set_ylabel("Frequency (Hz)")    plt.colorbar(im0, ax=axes[0], label="Power (dB)")    im1 = axes[1].pcolormesh(t1, f1, S1_db, shading="gouraud", cmap=cmap, vmin=-120, vmax=-100)    axes[1].set_title("ai1 (near) Spectrogram")    axes[1].set_ylabel("Frequency (Hz)")    plt.colorbar(im1, ax=axes[1], label="Power (dB)")        im2 = axes[2].pcolormesh(t1, f1, diff_db, shading="gouraud", cmap=diff_cmap, vmin=-diff_vlim, vmax=diff_vlim)    axes[2].set_title("ai1 - ai0 Diff Spectrogram")    axes[2].set_xlabel("Time (s)")    axes[2].set_ylabel("Frequency (Hz)")    plt.colorbar(im2, ax=axes[2], label="Near - Far (dB)")    fig.suptitle(        f"{record['filename']}\n"        f"leak={record['meta']['leak_quantity']} ml, "        f"distance={record['meta']['distance']*100:.0f} cm, "        f"pressure={record['meta']['pressure']} bar"    )    plt.tight_layout(rect=[0, 0, 1, 0.96])    if save_path:        save_path = Path(save_path)        save_path.parent.mkdir(parents=True, exist_ok=True)        plt.savefig(save_path, dpi=150, bbox_inches="tight")        plt.close(fig)        print(f"✅ 已儲存: {save_path}")    else:        plt.show()# ==========================# 3.1繪圖 ai0 / ai1 / diff(rms,raw signal)# ==========================# 繪圖：畫 ai0 / ai1 / diff 三條訊號，同一個檔案在同一張圖裡def plot_signal_overview(records, num_samples=5, save_dir="base_path/signal_plots"):    """    對每個檔案畫一張「多通道 + 能量分析」的總覽圖（overview plot）    1. 原始訊號（ai0 vs ai1）    2. rolling RMS（能量變化）    3. diff 訊號（near - far）    4. diff 的能量    """    save_dir = Path(save_dir)    save_dir.mkdir(parents=True, exist_ok=True)    for r in records[:num_samples]:          # 逐筆資料處理，每個 record 畫一張圖        ch0  = r["signal"]["ai0"]            # ai0 → far sensor        ch1  = r["signal"]["ai1"]            # ai1 → near sensor        diff = r["signal"]["diff"]           # diff → 空間差異（你 leak detection 很關鍵）        fs   = r["fs"]        t    = np.arange(len(ch0)) / fs      # 把 sample index → 秒，把 sample index → 秒        # 整體 RMS（全域能量）:比較 near / far 強度        rms0 = np.sqrt(np.mean(ch0 ** 2))        rms1 = np.sqrt(np.mean(ch1 ** 2))        channel_note = f"ai0 = far, ai1 = near, RMS ratio(ai1/ai0) = {rms1/(rms0+1e-12):.2f}"        # 局部能量 Rolling RMS        window = max(1, int(fs * 0.001))   # window = 1 ms，避免window = 0 → 直接壞掉        # 局部能量 = 移動平均(x^2) → 再開根號        rms0_roll = np.sqrt(np.convolve(ch0**2, np.ones(window)/window, mode='same'))        rms1_roll = np.sqrt(np.convolve(ch1**2, np.ones(window)/window, mode='same'))                # subplot 結構（4層）        fig, axes = plt.subplots(4, 1, figsize=(14, 14), dpi=150, sharex=True)        # (1) Raw signal(觀察振幅)        axes[0].plot(t, ch0, linewidth=0.5, color='steelblue', label=f"ai0 (RMS={rms0:.5f})")        axes[0].plot(t, ch1, linewidth=0.5, color='orange',    label=f"ai1 (RMS={rms1:.5f})")        axes[0].set_title("Raw Signal (ai0 vs ai1)")        axes[0].set_ylabel("Amplitude")        axes[0].legend()        # (2) Rolling RMS:能量誰比較強,leak 是否集中某段時間        axes[1].plot(t, rms0_roll, linewidth=1, color='steelblue', label="ai0 rolling RMS")        axes[1].plot(t, rms1_roll, linewidth=1, color='orange',    label="ai1 rolling RMS")        axes[1].set_title("Rolling RMS（能量趨勢）")        axes[1].set_ylabel("RMS")        axes[1].legend()        # (3) diff signal:空間差異,傳播效應        axes[2].plot(t, diff, linewidth=0.5, color='green')        axes[2].set_title("diff = ai1(near) - ai0(far)")        axes[2].set_ylabel("Amplitude")        # (4) diff 的能量:差異訊號是否有 structure        rms_diff_roll = np.sqrt(np.convolve(diff**2, np.ones(window)/window, mode='same'))        axes[3].plot(t, rms_diff_roll, linewidth=1, color='green')        axes[3].set_title("diff Rolling RMS")        axes[3].set_ylabel("RMS")        axes[3].set_xlabel("Time [s]")        # 設定標題：把 metadata + signal 整合在同一張圖        fig.suptitle(            f"{r['filename']}\n"            f"label={r['label']}  distance={r['meta']['distance']}m  "            f"pressure={r['meta']['pressure']}bar  leak={r['meta']['leak_quantity']}ml\n"            f"{channel_note}",            fontsize=11, fontweight='bold'        )        plt.tight_layout()        # 儲存圖片(每個record一張圖)        if save_dir:            fname = r['filename'].replace(".tdms", "_overview.png")            plt.savefig(os.path.join(save_dir, fname))            plt.close(fig)        else:            plt.show()    print("✅ 繪圖完成")# ============================================================# 圖 4：band energy summary（boxplot）# ============================================================def plot_band_energy_summary(records_leak,                              records_normal,                              bands,                              channel="ai1",                             label_leak="Baseline+Leak",                             label_normal="Baseline",                             save_path=None):    """    比較 Leak / Normal 在指定 channel 的 band energy 分布    channel 可選：    - ai0    - ai1    - diff    """    import matplotlib.patches as mpatches        # 建立 X 軸標籤    band_labels = [f"Band{i}\n{b['f_low']//1000}k~{b['f_high']//1000}k"                   for i, b in enumerate(bands)]        leak_energies   = []   # leak_energies[i] = 第 i 個 band 下，所有 leak 檔案的 energy    normal_energies = []   # normal_energies[i] = 第 i 個 band 下，所有 normal 檔案的 energy        # 逐 band 計算 energy,固定看主訊號(ai1)是因為要比較near 通道在不同 band 下，Leak 和 Normal 的群體差異。    for b in bands:        # 對每一筆 leak 資料：取出 ai1 -> 做 bandpass filter，只保留這個頻帶 -> 算 mean(filtered**2)，也就是 band energy        le = [np.mean(bandpass_filter(r["signal"][channel], r["fs"],                                      b["f_low"], b["f_high"]) ** 2)              for r in records_leak]        ne = [np.mean(bandpass_filter(r["signal"][channel], r["fs"],                                      b["f_low"], b["f_high"]) ** 2)              for r in records_normal]        leak_energies.append(le)        normal_energies.append(ne)    # 設定 X 軸位置    n_bands = len(bands)    x       = np.arange(n_bands)    width   = 0.35    # 建立畫布    fig, ax = plt.subplots(figsize=(max(10, n_bands * 1.4), 5.5), dpi=150)    # 繪製 boxplot    ax.boxplot(        leak_energies,        positions=x - width / 2,        widths=width * 0.8,        patch_artist=True,        boxprops=dict(facecolor="orange", alpha=0.6),        medianprops=dict(color="darkorange", linewidth=2),        whiskerprops=dict(color="orange"),        capprops=dict(color="orange"),        flierprops=dict(marker='o', color='orange', alpha=0.25)    )    ax.boxplot(        normal_energies,        positions=x + width / 2,        widths=width * 0.8,        patch_artist=True,        boxprops=dict(facecolor="steelblue", alpha=0.6),        medianprops=dict(color="darkblue", linewidth=2),        whiskerprops=dict(color="steelblue"),        capprops=dict(color="steelblue"),        flierprops=dict(marker='o', color='steelblue', alpha=0.25)    )    ax.set_yscale('log')    # 設定 y 軸為log scale,避免band energy差異太大    ax.set_xticks(x)    ax.set_xticklabels(band_labels, fontsize=9, rotation=20, ha="right")    ax.set_ylabel("Band Energy (mean filtered²)")    ax.set_title(f"Band Energy Summary: {label_leak} vs {label_normal} ({channel})")    leak_patch   = mpatches.Patch(color="orange",    alpha=0.6, label=f"{label_leak} (n={len(records_leak)})")    normal_patch = mpatches.Patch(color="steelblue", alpha=0.6, label=f"{label_normal} (n={len(records_normal)})")    ax.legend(handles=[leak_patch, normal_patch])    ax.grid(True, alpha=0.3, axis='y')    # 加上格線    plt.tight_layout()    if save_path:        Path(save_path).parent.mkdir(parents=True, exist_ok=True)        plt.savefig(save_path, dpi=150)        plt.close()        print(f"[Saved] {save_path}")    else:        plt.show()# ============================================================# 圖 5：雙通道比值 summary# ============================================================def plot_dual_channel_ratio_summary(records_leak, records_normal, bands, save_path=None):    """    把 Leak 與 Normal 在「雙通道關係」上的幾個關鍵 ratio 特徵畫成 boxplot，比較兩組分布差異。        三個比值指標的分布：    1. RMS(ai1) / RMS(ai0)    2. Band0_E_ai1 / Band0_E_ai0    3. Band0_E_diff / Band0_E_ai1        雙通道之間的相對關係，在 leak 和 normal 下有沒有明顯不同？    ai1 相對 ai0 是不是更強？    diff 相對 ai1 保留得怎麼樣？    """    import matplotlib.patches as mpatches    # 對一整組 records ,逐筆算出三種ratio    def compute_ratios(records, b0):        rms_ratios, band_ratios, diff_ratios = [], [], []        for r in records:   # 逐筆取出ai0,ai1,diff,採樣率            ai0  = r["signal"]["ai0"]            ai1  = r["signal"]["ai1"]            diff = r["signal"]["diff"]            fs   = r["fs"]                        # 近端 / 遠端整體強度比            rms0 = np.sqrt(np.mean(ai0 ** 2))            rms1 = np.sqrt(np.mean(ai1 ** 2))            rms_ratios.append(rms1 / (rms0 + 1e-12))                        # 針對 Band0(取決於傳進來的band是哪個區間)：分別把 ai1、ai0、diff 做 bandpass,再算 band energy            E_ai1 = np.mean(bandpass_filter(ai1,  fs, b0["f_low"], b0["f_high"]) ** 2)            E_ai0 = np.mean(bandpass_filter(ai0,  fs, b0["f_low"], b0["f_high"]) ** 2)            E_diff = np.mean(bandpass_filter(diff, fs, b0["f_low"], b0["f_high"]) ** 2)            band_ratios.append(E_ai1 / (E_ai0  + 1e-12))    # 在 Band0 裡，near 比 far 強多少,更聚焦在「最重要的那個 band」            diff_ratios.append(E_diff / (E_ai1 + 1e-12))    # 差分訊號在 Band0 中，保留了多少 near 的主能量        return rms_ratios, band_ratios, diff_ratios    b0 = bands[0]   # 假設 Band 0 是最重要的，先看他的雙公道關係    leak_rms,   leak_band,   leak_diff   = compute_ratios(records_leak,   b0)    normal_rms, normal_band, normal_diff = compute_ratios(records_normal, b0)        # 把三個指標整理成 metrics    metrics = [        ("RMS(ai1) / RMS(ai0)",         leak_rms,   normal_rms),        (f"Band0 E(ai1) / E(ai0)\n({b0['f_low']//1000}k~{b0['f_high']//1000}kHz)",         leak_band,  normal_band),        (f"Band0 E(diff) / E(ai1)\n({b0['f_low']//1000}k~{b0['f_high']//1000}kHz)",         leak_diff,  normal_diff),    ]    fig, axes = plt.subplots(1, 3, figsize=(15, 5), dpi=150)    # 建立畫布(一列三欄)    # 畫 boxplot(畫兩個箱型圖，第一個是leak,第二個是Normal)    for ax, (title, leak_vals, normal_vals) in zip(axes, metrics):        bp = ax.boxplot(            [leak_vals, normal_vals],            patch_artist=True,            labels=["Baseline+Leak", "Baseline"],            boxprops=dict(alpha=0.7),            medianprops=dict(linewidth=2)        )        # 手動改顏色        bp["boxes"][0].set_facecolor("orange")        bp["boxes"][1].set_facecolor("steelblue")        bp["medians"][0].set_color("darkorange")        bp["medians"][1].set_color("darkblue")        ax.set_yscale('log')   # 設定log scale        ax.set_title(title, fontsize=9)        ax.set_ylabel("Ratio")        ax.grid(True, alpha=0.3, axis='y')        ax.axhline(1.0, color='gray', linestyle='--', linewidth=1, label='ratio=1')   # axhline(1.0)：畫一條 ratio=1 的虛線,當作分界點，ratio > 1：分子比較大        ax.legend(fontsize=7)            # 整張圖的標題    plt.suptitle("Dual Channel Ratio Summary: Baseline+Leak vs Baseline", fontweight='bold')    plt.tight_layout()    if save_path:        Path(save_path).parent.mkdir(parents=True, exist_ok=True)        plt.savefig(save_path, dpi=150)        plt.close()        print(f"[Saved] {save_path}")    else:        plt.show()        # ============================================================  # 放大重要頻段訊號圖# ============================================================        def plot_band_zoom_comparison(records_leak, records_normal, band,                               num_samples=None,    # ← None = 全部                               alpha=0.2,           # ← 可調透明度                               save_path=None):    """    把 leak 和 normal 的同一個 band 疊在一張圖上做直接比較     - 挑一個 band     - 把很多筆 leak 疊一起     - 把很多筆 normal 疊一起     - 看這個 band 下，兩組的波形與能量輪廓到底差多少         上圖     - bandpass 後的 waveform 疊圖     - 橘色：Leak     - 藍色：Normal    看的是：這個 band 的原始振動波形長怎樣        下圖     - envelope 疊圖     - 橘色：Leak     - 藍色：Normal    看的是：這個 band 的能量輪廓差異    """    from scipy.signal import hilbert    # 建立畫布:2個子圖(2列1欄)    fig, axes = plt.subplots(2, 1, figsize=(14, 8), dpi=150, sharex=True)        # num_samples=None 時畫全部    n_leak   = len(records_leak)   if num_samples is None else num_samples    n_normal = len(records_normal) if num_samples is None else num_samples        # 上圖：raw filtered waveform 疊圖    # 對每一筆Leak:取出 ai1 -> 做 bandpass filter，只保留指定頻帶 -> 建立時間軸 -> 畫出這個 band 的波形(橘色)    for r in records_leak[:num_samples]:        sig      = r["signal"]["ai1"]        fs       = r["fs"]        filtered = bandpass_filter(sig, fs, band["f_low"], band["f_high"])        t        = np.arange(len(filtered)) / fs        axes[0].plot(t[::10], filtered[::10],                     color="orange", alpha=0.5, linewidth=0.8)    # normal:藍色    for r in records_normal[:num_samples]:        sig      = r["signal"]["ai1"]        fs       = r["fs"]        filtered = bandpass_filter(sig, fs, band["f_low"], band["f_high"])        t        = np.arange(len(filtered)) / fs        axes[0].plot(t[::10], filtered[::10],                     color="steelblue", alpha=0.5, linewidth=0.8)    axes[0].set_title(        f"Bandpass {band['f_low']//1000}k~{band['f_high']//1000}kHz — "        f"Baseline+Leak(橘) vs Baseline(藍) waveform"    )    axes[0].set_ylabel("Amplitude")    # 下圖：envelope 疊圖（更清楚看能量差）    # 對每一筆Leak:取出 ai1 -> 做 bandpass filter，只保留指定頻帶 -> 用 Hilbert transform 算 envelope -> 算 RMS -> 把 envelope 畫出來(橘色)    for r in records_leak[:num_samples]:        sig      = r["signal"]["ai1"]        fs       = r["fs"]        filtered = bandpass_filter(sig, fs, band["f_low"], band["f_high"])        env      = np.abs(hilbert(filtered))   # 取出這個 band 的能量外框        rms      = np.sqrt(np.mean(filtered**2))        t        = np.arange(len(env)) / fs        axes[1].plot(t[::10], env[::10],                     color="orange", alpha=0.6, linewidth=1.0,                     label=f"leak RMS={rms:.2e}")    # normal:藍色    for r in records_normal[:num_samples]:        sig      = r["signal"]["ai1"]        fs       = r["fs"]        filtered = bandpass_filter(sig, fs, band["f_low"], band["f_high"])        env      = np.abs(hilbert(filtered))        rms      = np.sqrt(np.mean(filtered**2))        t        = np.arange(len(env)) / fs        axes[1].plot(t[::10], env[::10],                     color="steelblue", alpha=0.6, linewidth=1.0,                     label=f"normal E={rms:.2e}")    axes[1].set_title("Envelope 比較（能量差異）")    axes[1].set_ylabel("Envelope Amplitude")    axes[1].set_xlabel("Time [s]")    axes[1].legend(fontsize=7, ncol=2)    plt.suptitle(        f"Band Zoom: {band['f_low']//1000}k~{band['f_high']//1000}kHz",        fontweight='bold'    )    plt.tight_layout()    if save_path:        Path(save_path).parent.mkdir(parents=True, exist_ok=True)        plt.savefig(save_path, dpi=150)        plt.close()        print(f"[Saved] {save_path}")    else:        plt.show()      # ============================================================# 同一個類別內，比較兩個通道 ai0(far) vs ai1(near)的 PSD# ============================================================def plot_within_label_dual_channel_psd(    records,                    # 同一類別的資料列表，每筆 record 應包含 signal 與 fs    label_name="Baseline",      # 圖上顯示的類別名稱    save_path=None,             # 若有指定路徑則存圖，否則直接顯示    nperseg=NPERSEG,            # PSD 計算時每段長度    smooth_sigma=1.0,           # 平滑用的高斯 sigma，越大越平滑    fmin=0,                     # 顯示的最低頻率    fmax=None,                  # 顯示的最高頻率，若不指定則用 Nyquist 頻率    mark_low=5_000,             # 主觀察頻帶下限    mark_high=70_000,           # 主觀察頻帶上限    aux_low=420_000,            # 輔助觀察頻帶下限    aux_high=470_000,           # 輔助觀察頻帶上限):    from scipy.ndimage import gaussian_filter1d    # 匯入一維高斯平滑函式，用來讓 PSD 曲線更平順    # 如果沒有指定最高頻率，就用取樣頻率一半（Nyquist frequency）    if fmax is None:        fmax = FS / 2    # ------------------------------------------------------------    # 內部函式：計算某個 channel 在多筆 records 上的平均 PSD    # ------------------------------------------------------------    def avg_psd(records, channel):        psd_list = []     # 用來收集每筆資料算出的 PSD        f_ref = None      # 用來保存對應的頻率軸        # 逐筆處理資料        for r in records:            # 取出指定通道的訊號，並轉成 float 的 numpy array            x = np.asarray(r["signal"][channel], dtype=float)                        # 取出這筆資料的取樣頻率            fs = float(r["fs"])                        # 計算該筆訊號的 PSD, smooth_sigma=0 表示先不要在 compute_psd 裡做平滑            f, Pxx = compute_psd(                x, fs,                nperseg=nperseg,                normalize=False,                smooth_sigma=0            )            # # 建立頻率範圍遮罩，只保留 fmin ~ fmax 之間的頻率            mask = (f >= fmin) & (f <= fmax)            f = f[mask]      # 套用遮罩，保留目標頻段            Pxx = Pxx[mask]            psd_list.append(Pxx)     # 把這筆資料的 PSD 加入列表            f_ref = f                # 記住頻率軸，後面畫圖要用        if len(psd_list) == 0:       # 如果沒有任何資料，回傳空值            return None, None        # 把多筆 PSD 做幾何平均        mean_psd = np.exp(np.mean(np.log(np.array(psd_list) + 1e-12), axis=0))        # 如果有指定平滑參數，就再做一次高斯平滑        if smooth_sigma and smooth_sigma > 0:            mean_psd = gaussian_filter1d(mean_psd, sigma=smooth_sigma)        # 回傳頻率軸與平均 PSD        return f_ref, mean_psd        # 分別計算 ai0 與 ai1 的平均 PSD    f0, P0 = avg_psd(records, "ai0")    f1, P1 = avg_psd(records, "ai1")    # 如果任一通道沒有足夠資料，就印出警告並結束    if f0 is None or f1 is None:        print(f"⚠️ {label_name} 沒有足夠資料可畫 ai0 vs ai1 PSD")        return    # 建立圖表，設定尺寸與解析度    plt.figure(figsize=(12, 6), dpi=160)    # 畫 ai0 的 PSD 曲線，使用半對數座標（y 軸為 log）    plt.semilogy(f0, P0, color="steelblue", linewidth=2, label=f"{label_name} ai0 (far)")    # 畫 ai1 的 PSD 曲線    plt.semilogy(f1, P1, color="tomato", linewidth=2, label=f"{label_name} ai1 (near)")    # 用淡金色區塊標出核心觀察頻段 5k ~ 70k    plt.axvspan(mark_low, mark_high, color="gold", alpha=0.08, label="Core 5–70k")    # 畫出核心觀察頻段的左右邊界線    plt.axvline(mark_low, color="goldenrod", linestyle="--", linewidth=1.0)    plt.axvline(mark_high, color="goldenrod", linestyle="--", linewidth=1.0)    # 用淡紅色區塊標出輔助觀察頻段 420k ~ 470k    plt.axvspan(aux_low, aux_high, color="crimson", alpha=0.08, label="Aux 420–470k")    plt.xlim(fmin, fmax)                      # 設定 x 軸範圍    plt.xlabel("Frequency (Hz)")              # 設定 x 軸標籤    plt.ylabel("PSD")                         # 設定 y 軸標籤    plt.title(f"{label_name}: ai0 vs ai1")    # 設定圖標題    plt.legend()                              # 顯示圖例    plt.tight_layout()                        # 自動調整版面，避免標籤被截掉    # 如果有指定儲存路徑    if save_path:        save_path = Path(save_path)    # 轉成 Path 物件        save_path.parent.mkdir(parents=True, exist_ok=True)        plt.savefig(save_path, dpi=150, bbox_inches="tight")        plt.close()        print(f"✅ 已儲存: {save_path}")    else:   # 若沒指定儲存路徑，就直接顯示圖        plt.show()# ============================================================# 同一通道跨類別 PSD：Leak0 vs Leak1, 固定某個 channel（例如 ai1），比較 Leak0 與 Leak1 的平均 PSD# ============================================================def plot_cross_label_same_channel_psd(    records_normal,          # 正常類別資料，例如 Leak0    records_leak,            # 異常類別資料，例如 Leak1    channel="ai1",           # 要比較的通道，預設 ai1    save_path=None,          # 若有指定路徑則存圖，否則直接顯示    nperseg=NPERSEG,         # PSD 計算時每段長度    smooth_sigma=1.0,        # 平滑用的高斯 sigma    fmin=0,                  # 顯示的最低頻率    fmax=None,               # 顯示的最高頻率    mark_low=5_000,          # 主觀察頻帶下限    mark_high=70_000,        # 主觀察頻帶上限    aux_low=420_000,         # 輔助觀察頻帶下限    aux_high=470_000,        # 輔助觀察頻帶上限):    from scipy.ndimage import gaussian_filter1d    # 如果沒有指定最高頻率，就自動設成 FS/2    if fmax is None:        fmax = FS / 2    # ------------------------------------------------------------    # 內部函式：把一整組 records 算成一條平均 PSD 曲線    # ------------------------------------------------------------    def avg_psd(records):        psd_list = []      # 收集每一筆資料算出來的 PSD        f_ref = None       # 記錄頻率軸 f        # 逐筆處理這一組資料        for r in records:            x = np.asarray(r["signal"][channel], dtype=float)     # 從每一筆資料 r 中，抓出指定通道的訊號            fs = float(r["fs"])            f, Pxx = compute_psd(     # 計算 PSD, f：頻率座標, Pxx：每個頻率對應的功率譜密度                x, fs,                nperseg=nperseg,                normalize=False,                smooth_sigma=0            )            # 做頻率範圍篩選:只保留 fmin ~ fmax 之間的頻率            mask = (f >= fmin) & (f <= fmax)            f = f[mask]            Pxx = Pxx[mask]            psd_list.append(Pxx)            f_ref = f        # 如果這組資料根本沒有內容，就直接回傳空值，避免後面出錯        if len(psd_list) == 0:            return None, None        # 計算多筆 PSD 的幾何平均：先取 log -> 對每個頻率位置做平均 -> 再用 exp 轉回原本尺度        mean_psd = np.exp(np.mean(np.log(np.array(psd_list) + 1e-12), axis=0))        # 如果有設定平滑參數，就把平均 PSD 再做一次高斯平滑        if smooth_sigma and smooth_sigma > 0:            mean_psd = gaussian_filter1d(mean_psd, sigma=smooth_sigma)        return f_ref, mean_psd    # 對兩個類別分別算平均 PSD    fn, Pn = avg_psd(records_normal)    fl, Pl = avg_psd(records_leak)    # 如果任一組沒有資料，就印警告並停止    if fn is None or fl is None:        print(f"⚠️ {channel} 沒有足夠資料可畫 Leak0 vs Leak1 PSD")        return    # 繪圖：畫兩條 PSD 曲線 -> 藍色：Leak0 / 紅色：Leak1    plt.figure(figsize=(12, 6), dpi=160)    plt.semilogy(fn, Pn, color="steelblue", linewidth=2, label=f"Leak0 {channel}")    plt.semilogy(fl, Pl, color="tomato", linewidth=2, label=f"Leak1 {channel}")    plt.axvspan(mark_low, mark_high, color="gold", alpha=0.08, label="Core 5–70k")        # 畫一塊淡金色背景，表示你特別關注 5k ~ 70k Hz。    plt.axvline(mark_low, color="goldenrod", linestyle="--", linewidth=1.0)    plt.axvline(mark_high, color="goldenrod", linestyle="--", linewidth=1.0)    plt.axvspan(aux_low, aux_high, color="crimson", alpha=0.08, label="Aux 420–470k")     # 畫第二個重點區間 420k ~ 470k Hz    # 設定圖表資訊    plt.xlim(fmin, fmax)    plt.xlabel("Frequency (Hz)")    plt.ylabel("PSD")    plt.title(f"{channel}: Leak0 vs Leak1")    plt.legend()    plt.tight_layout()    if save_path:        save_path = Path(save_path)        save_path.parent.mkdir(parents=True, exist_ok=True)        plt.savefig(save_path, dpi=150, bbox_inches="tight")        plt.close()        print(f"✅ 已儲存: {save_path}")    else:        plt.show()# ============================================================# 固定同一個 channel，比較兩組條件的平均 PSD, 例如：normal(ai1) vs ai1# ============================================================def plot_cross_condition_same_channel_psd(    records_a,               # 要比較的資料    records_b,               # 要比較的資料    channel="ai1",           # 指定比較哪個通道,可用 "ai0"、"ai1"、"diff"    label_a="Baseline",        # 圖例和標題顯示名稱    label_b="Baseline+60",    save_path=None,          # 如果有給路徑就存圖，沒有就直接顯示    nperseg=NPERSEG,         # Welch PSD 的分段長度    smooth_sigma=1.0,        # Gaussian 平滑強度    fmin=0,                  # 顯示的頻率範圍    fmax=None,    mark_low=5_000,          # 核心頻段標示區間    mark_high=70_000,        # 核心頻段標示區間    aux_low=420_000,         # 輔助頻段標示區間    aux_high=470_000,        # 輔助頻段標示區間):    from scipy.ndimage import gaussian_filter1d    # 設定最高頻率(沒有手動指定 fmax，就用 Nyquist 頻率，也就是採樣率的一半)    if fmax is None:        fmax = FS / 2    # ------------------------------------------------------------    # 內部函式：把一組 records 的指定通道，全部算 PSD，再合成一條代表性的平均 PSD 曲線    # ------------------------------------------------------------    def avg_psd(records):        psd_list = []     # 收每一筆資料的 PSD        f_ref = None      # 記錄頻率軸，最後畫圖要用        # 逐筆算 PSD        for r in records:            x = np.asarray(r["signal"][channel], dtype=float)     # 指定通道的訊號 x            fs = float(r["fs"])                                   # 採樣率 fs            # 呼叫 compute_psd(),計算出f：頻率軸, Pxx：對應的 PSD            f, Pxx = compute_psd(                x, fs,                nperseg=nperseg,                normalize=False,     # 保留原始 PSD 強度，不做最大值正規化                smooth_sigma=0       # 先不要在每一筆資料層級做平滑            )            # 限制顯示頻率範圍(只保留關心的頻率區間)            mask = (f >= fmin) & (f <= fmax)            f = f[mask]            Pxx = Pxx[mask]            # 儲存每筆 PSD,之後做平均            psd_list.append(Pxx)            f_ref = f        if len(psd_list) == 0:            return None, None        mean_psd = np.exp(np.mean(np.log(np.array(psd_list) + 1e-12), axis=0))        if smooth_sigma and smooth_sigma > 0:            mean_psd = gaussian_filter1d(mean_psd, sigma=smooth_sigma)        return f_ref, mean_psd    fa, Pa = avg_psd(records_a)    fb, Pb = avg_psd(records_b)    if fa is None or fb is None:        print(f"⚠️ {label_a} vs {label_b} ({channel}) 沒有足夠資料可畫 PSD")        return    plt.figure(figsize=(12, 6), dpi=160)    plt.semilogy(fa, Pa, color="steelblue", linewidth=2, label=f"{label_a} {channel}")    plt.semilogy(fb, Pb, color="tomato", linewidth=2, label=f"{label_b} {channel}")    plt.axvspan(mark_low, mark_high, color="gold", alpha=0.08, label="Core 5–70k")    plt.axvline(mark_low, color="goldenrod", linestyle="--", linewidth=1.0)    plt.axvline(mark_high, color="goldenrod", linestyle="--", linewidth=1.0)    plt.axvspan(aux_low, aux_high, color="crimson", alpha=0.08, label="Aux 420–470k")    plt.xlim(fmin, fmax)    plt.xlabel("Frequency (Hz)")    plt.ylabel("PSD")    plt.title(f"{label_a} vs {label_b} ({channel})")    plt.legend()    plt.tight_layout()    if save_path:        save_path = Path(save_path)        save_path.parent.mkdir(parents=True, exist_ok=True)        plt.savefig(save_path, dpi=150, bbox_inches="tight")        plt.close()        print(f"✅ 已儲存: {save_path}")    else:        plt.show()# ============================================================# 從整體角度看 normal 與 leak 兩類資料中，far/near 的平均 PSD 長什麼樣# ============================================================def plot_label_overview_psd(    normal_records,    # normal 類別的 records    leak_records,      # leak 類別的 records    out_path=None,         smooth_sigma=1.0,  # 是否做平滑    nperseg=NPERSEG,   # PSD 計算參數):    """    畫一張只分 normal / leak 的總覽 PSD 圖：    - 左圖：normal 的 ai0(far) vs ai1(near)    - 右圖：leak 的 ai0(far) vs ai1(near)    """    from scipy.ndimage import gaussian_filter1d    eps = 1e-12    # 避免後面幾何平均時 log(0) 出問題    def mean_psd(records, ch_name):        '''給一批 records 和一個 channel 名稱，算出這批資料在該 channel 的平均 PSD'''        psd_list = []    # 收集每筆 record 的 PSD        f_ref = None     # 記住頻率軸        # 對每筆資料算 PSD        for r in records:            x = np.asarray(r["signal"][ch_name], dtype=float)    # 某筆 record 的指定 channel 訊號            fs = float(r["fs"])            f, Pxx = compute_psd(x, fs, nperseg=nperseg, normalize=False, smooth_sigma=0)    # 算出頻率與功率譜            # 只保留 FREQ_MIN 以上            mask = f >= FREQ_MIN            f = f[mask]            Pxx = Pxx[mask]            # 收集 PSD            psd_list.append(Pxx)            f_ref = f                    # 如果沒資料就回傳空        if len(psd_list) == 0:            return None, None        # 計算平均 PSD        mean_psd = np.exp(np.mean(np.log(np.array(psd_list) + eps), axis=0))        # 做平滑(如果有指定 smooth_sigma，就把平均後的 PSD 曲線平滑一下)        if smooth_sigma and smooth_sigma > 0:            mean_psd = gaussian_filter1d(mean_psd, sigma=smooth_sigma)        return f_ref, mean_psd    # 分別算四條曲線    f_n0, P_n0 = mean_psd(normal_records, "ai0")    # normal 的 far    f_n1, P_n1 = mean_psd(normal_records, "ai1")    # normal 的 near    f_l0, P_l0 = mean_psd(leak_records, "ai0")      # leak 的 far    f_l1, P_l1 = mean_psd(leak_records, "ai1")      # leak 的 near    # 建立兩張子圖(sharey=True, 左右圖共用同一個 y 軸尺度)    fig, axes = plt.subplots(1, 2, figsize=(14, 5.5), dpi=160, sharey=True)    # 左圖畫 normal(在 normal 類別中的平均 PSD)    if f_n0 is not None and f_n1 is not None:        axes[0].semilogy(f_n0, P_n0, color="steelblue", label="ai0 = far", linewidth=1.5)        axes[0].semilogy(f_n1, P_n1, color="tomato", label="ai1 = near", linewidth=1.5)        axes[0].set_title("Baseline - Mean PSD")        axes[0].set_xlabel("Frequency (Hz)")        axes[0].set_ylabel("PSD")        axes[0].grid(True, alpha=0.25)        axes[0].legend()    # 右圖畫 leak(在 leak 類別中的平均 PSD)    if f_l0 is not None and f_l1 is not None:        axes[1].semilogy(f_l0, P_l0, color="steelblue", label="ai0 = far", linewidth=1.5)        axes[1].semilogy(f_l1, P_l1, color="tomato", label="ai1 = near", linewidth=1.5)        axes[1].set_title("Baseline+Leak - Mean PSD")        axes[1].set_xlabel("Frequency (Hz)")        axes[1].grid(True, alpha=0.25)        axes[1].legend()    plt.tight_layout()    if out_path is not None:        out_path = Path(out_path)        out_path.parent.mkdir(parents=True, exist_ok=True)        plt.savefig(out_path, bbox_inches="tight")        plt.close()        print(f"✅ normal/leak 總覽 PSD 圖已儲存: {out_path}")    else:        plt.show()# ============================================================# 兩組條件的箱型圖比較# ============================================================def plot_top_features_pairwise_boxplot(        record_df,                # 每列是一個 record，每欄是一個特徵        rank_df,                  # 特徵排名表，至少要有 feature 欄，最好還有像 d_0_50 這種效果量欄位        level_a=0,                # 比較哪兩組，像 0 和 50        level_b=60,               label_a="Baseline",       # 圖上顯示名稱        label_b="Baseline+60",        top_n=12,                 # 只畫前幾名特徵        save_path=None,        showfliers=True,         # 箱型圖要不要顯示離群值點        robust_ylim=True,        # 要不要用穩健方式限制 y 軸範圍，避免極端值把圖撐壞         lower_pct=2,        upper_pct=98,    ):    """    畫兩組條件的 top feature boxplot    例如：    - Baseline vs Baseline+30    - Baseline vs Baseline+50    """    # 從整張 record-level 表中,只挑出 level_a 和 level_b 這兩組    df = record_df.copy()    df = df[df["leak_quantity"].isin([level_a, level_b])].copy()    # 從 ranking 裡拿前幾名特徵    top_features = rank_df.head(top_n)["feature"].tolist()    if len(top_features) == 0:    # 如果沒有特徵就結束        print("⚠️ 沒有可畫的特徵")        return    # 建立畫布及設定    n_cols = 4    n_rows = (len(top_features) + n_cols - 1) // n_cols    fig, axes = plt.subplots(n_rows, n_cols, figsize=(16, n_rows * 3.2), dpi=160)    axes = np.atleast_1d(axes).flatten()    # 決定要顯示哪個 Cohen’s d 欄位    d_col = f"d_{int(level_a)}_{int(level_b)}"    if d_col not in rank_df.columns:        d_col = f"d_{int(level_b)}_{int(level_a)}"    if d_col not in rank_df.columns:        d_col = None    # 把 feature -> d值 做成字典    d_map = {}    if d_col is not None and d_col in rank_df.columns:        d_map = dict(zip(rank_df["feature"], rank_df[d_col]))    # 逐個特徵畫圖    for idx, feat in enumerate(top_features):        ax = axes[idx]        # 準備這兩組特徵值        data_to_plot = [            df.loc[df["leak_quantity"] == level_a, feat].dropna(),            df.loc[df["leak_quantity"] == level_b, feat].dropna(),        ]        bp = ax.boxplot(            data_to_plot,            tick_labels=[label_a, label_b],            patch_artist=True,            showfliers=showfliers        )        bp["boxes"][0].set_facecolor("lightblue")        bp["boxes"][1].set_facecolor("khaki" if level_b == 50 else "lightcoral")                # 如果有開 robust_ylim，就限制 y 軸        if robust_ylim:            _set_robust_ylim(                ax,                data_to_plot,                lower_pct=lower_pct,                upper_pct=upper_pct,                pad_ratio=0.08            )        d_val = d_map.get(feat, np.nan)    # 取出這個特徵的 Cohen’s d        if pd.notna(d_val):            ax.set_title(f"{feat}\n(Cohen's d = {d_val:.2f})", fontsize=9)        else:            ax.set_title(feat, fontsize=9)        ax.grid(True, alpha=0.3, axis="y")    for idx in range(len(top_features), len(axes)):        axes[idx].axis("off")    suffix = " (robust view)" if robust_ylim and not showfliers else ""    plt.suptitle(        f"{label_a} vs {label_b} - Record-level Feature Comparison",        fontsize=14,        fontweight="bold"    )    plt.tight_layout()    if save_path:        Path(save_path).parent.mkdir(parents=True, exist_ok=True)        plt.savefig(save_path, dpi=150, bbox_inches="tight")        plt.close(fig)        print(f"✅ 已儲存: {save_path}")    else:        plt.show()# ============================================================# 同一個特徵從 Baseline -> +30 ，整體分布趨勢長什麼樣# ============================================================def plot_top_features_multilevel_boxplot(        record_df,                               # record-level 特徵表        rank_df,                                 # 特徵排名表，決定哪幾個特徵要畫        target_levels=None,       # 一次要放進圖裡的 leak levels，預設 0, 30        top_n=20,                                # 只畫前幾名特徵        save_path=None,          showfliers=False,                        # 箱型圖是否顯示離群值        robust_ylim=True,                        # 是否使用穩健 y 軸範圍        lower_pct=2,        upper_pct=98):    """    特徵有沒有隨 leak level 呈現趨勢    哪些特徵在多個 leak level 間有層次感    微小洩漏 +30 是否已開始偏移    """    # 檢查    if target_levels is None:        raise ValueError("請傳入 target_levels，例如 target_levels=tuple(ANALYSIS_LEVELS)")        # 只保留要的 leak levels:target_levels=None    df = record_df.copy()    df = df[df["leak_quantity"].isin(target_levels)].copy()    # 從排名表取前幾個特徵    top_features = rank_df.head(top_n)["feature"].tolist()    # 如果沒有特徵可畫就退出    if len(top_features) == 0:        print("⚠️ 沒有可畫的特徵")        return    # 整理 leak levels 順序與顯示名稱    sorted_levels = sorted(target_levels)    level_labels = [f"Baseline+{int(lv)}" if lv != 0 else "Baseline" for lv in sorted_levels]    # 設定畫圖排版，每列放 4 張小圖，自動算需要幾列    n_cols = 4    n_rows = (len(top_features) + n_cols - 1) // n_cols    # 建立畫布    fig, axes = plt.subplots(n_rows, n_cols, figsize=(16, n_rows * 3.4), dpi=160)    axes = np.atleast_1d(axes).flatten()    # 設定各 leak level 的顏色    color_map = {        0: "lightblue",        30: "khaki",    }    # 逐個特徵畫圖    for idx, feat in enumerate(top_features):        ax = axes[idx]        # 準備這個特徵在各 leak level 的資料        data_to_plot = [            df.loc[df["leak_quantity"] == lv, feat].dropna()            for lv in sorted_levels        ]        bp = ax.boxplot(            data_to_plot,            tick_labels=level_labels,            patch_artist=True,            showfliers=showfliers        )        for box, lv in zip(bp["boxes"], sorted_levels):            box.set_facecolor(color_map.get(lv, "lightgray"))                    # 如果有開 robust_ylim，就調整 y 軸        if robust_ylim:            _set_robust_ylim(                ax,                data_to_plot,                lower_pct=lower_pct,                upper_pct=upper_pct,                pad_ratio=0.08            )        ax.set_title(feat, fontsize=9)        ax.grid(True, alpha=0.3, axis="y")        ax.tick_params(axis="x", rotation=25)    # 多餘空子圖關掉    for idx in range(len(top_features), len(axes)):        axes[idx].axis("off")    # 準備總標題的 suffix    suffix = " (robust view)" if robust_ylim and not showfliers else ""    plt.suptitle(        f"Baseline vs Baseline+30 - Record-level Feature Comparison{suffix}",        fontsize=14,        fontweight="bold"    )    plt.tight_layout()    if save_path:        save_path = Path(save_path)        save_path.parent.mkdir(parents=True, exist_ok=True)        plt.savefig(save_path, dpi=150, bbox_inches="tight")        plt.close(fig)        print(f"✅ 已儲存: {save_path}")    else:        plt.show()               # ============================================================# 趨勢折線圖，同一個特徵，隨 leak quantity 變化的折線圖，並把不同距離分成不同顏色# ============================================================def plot_top_features_multilevel_lines(    record_df,                           # record-level 特徵表    rank_df,                             # 特徵排名表，用來決定畫哪些特徵    target_levels=None,   # 要看的 leak levels，例如 0, 30    top_n=20,                            # 只畫前幾名特徵    out_dir=None,):    """    1.挑出排名前 top_n 的特徵    2.對每個特徵，依 distance_cm × leak_quantity 分組    3.算每組的 record-level 中位數    4.每個距離畫成一條線    5.看不同距離下，特徵是否隨 leak quantity 有一致趨勢    """    # 檢查    if target_levels is None:        raise ValueError("請傳入 target_levels，例如 target_levels=tuple(ANALYSIS_LEVELS)")        # 先只保留指定 leak levels    df = record_df.copy()    df = df[df["leak_quantity"].isin(target_levels)].copy()    # 取前幾名特徵    features_to_plot = rank_df.head(top_n)["feature"].tolist()    # 如果有指定輸出資料夾，就先建立    if out_dir is not None:        out_dir = Path(out_dir)        out_dir.mkdir(parents=True, exist_ok=True)    # 逐個特徵畫圖    for feat in features_to_plot:        if feat not in df.columns:            continue                # 依距離與 leak level 分組，取中位數        g = (            df.groupby(["distance_cm", "leak_quantity"])[feat]            .median()            .reset_index()            .sort_values(["distance_cm", "leak_quantity"])        )        # 如果這個特徵沒有資料就跳過        if g.empty:            continue        plt.figure(figsize=(8, 5), dpi=160)        # 每個距離各畫一條線        for dist, sub in g.groupby("distance_cm"):            plt.plot(                sub["leak_quantity"],                sub[feat],                marker="o",                linewidth=1.8,                label=f"{int(dist)} cm"            )        plt.title(f"{feat} vs Leak Quantity")        plt.xlabel("Leak Quantity (ml)")        plt.ylabel(f"{feat} (record-level median)")        plt.xticks(sorted(target_levels))        plt.legend(title="Distance")        plt.grid(True, alpha=0.25)        plt.tight_layout()        if out_dir is not None:            plt.savefig(out_dir / f"{feat}_multilevel.png", bbox_inches="tight")            plt.close()        else:            plt.show()    if out_dir is not None:        print(f"✅ 多層 leak 趨勢圖已存到: {out_dir}")# ============================================================# 畫前幾個重要特徵的折線圖：x=leak_quantity, color=distance_cm# ============================================================def plot_selected_feature_lines_by_leak_and_distance(        record_df,        features_to_plot,        out_dir=None,        label_filter=1,        line_alpha=0.65,     # 線透明度        marker_size=7,       # 點大小        marker_edge_color="white",   # 點外框顏色        marker_edge_width=0.8,       # 點外框寬度    ):    """    每張圖一個 feature    x 軸 = leak_quantity    不同顏色 = distance_cm    y 軸 = record-level median feature    """    df = record_df.copy()    # 如果有指定 label_filter，就先只看某個類別    if label_filter is not None:        df = df[df["label"] == label_filter].copy()    # 如果指定輸出資料夾，就先建立它    if out_dir is not None:        out_dir = Path(out_dir)        out_dir.mkdir(parents=True, exist_ok=True)    # 開始逐個 feature 畫圖    for feat in features_to_plot:        if feat not in df.columns:    # 如果這個 feature 不存在，直接跳過            continue        # 按 distance_cm 和 leak_quantity 分組 -> 對該 feature 算中位數 -> 轉回一般表格 -> 排序        g = (            df.groupby(["distance_cm", "leak_quantity"])[feat]            .median()            .reset_index()            .sort_values(["distance_cm", "leak_quantity"])        )        if g.empty:            continue                # 建立一張圖        plt.figure(figsize=(8, 5), dpi=160)                colors = plt.cm.tab10.colors         # 比較清楚的配色        n_dist = g["distance_cm"].nunique()        offsets = np.linspace(-3, 3, n_dist) if n_dist > 1 else np.array([0.0])     # 每條線一點點水平位移                # 針對每個 distance_cm, 各自畫一條線, x 軸是 leak_quantity, y 軸是 feature 中位數        for i, (dist, sub) in enumerate(g.groupby("distance_cm")):            x = sub["leak_quantity"].to_numpy(dtype=float) + offsets[i]                        plt.plot(                x,                sub[feat],                marker="o",                markersize=marker_size,                linewidth=1.8,                alpha=line_alpha,                color=colors[i % len(colors)],                markerfacecolor=colors[i % len(colors)],                markeredgecolor=marker_edge_color,                markeredgewidth=marker_edge_width,                label=f"{int(dist)} cm"            )                    xticks = sorted(g["leak_quantity"].unique())        plt.xticks(            xticks,            ["Baseline" if int(v) == 0 else f"Baseline+{int(v)}" for v in xticks]        )        plt.title(f"{feat} vs Leak Level Relative to Baseline (dev)")        plt.xlabel("Leak Level Relative to Baseline (ml)")        plt.ylabel(f"{feat} (record-level median)")        plt.legend(title="Distance")        plt.grid(True, alpha=0.25)        plt.tight_layout()        if out_dir is not None:            save_path = out_dir / f"{feat}_vs_leak_quantity.png"            plt.savefig(save_path, bbox_inches="tight")            plt.close()        else:            plt.show()    if out_dir is not None:        print(f"✅ 折線圖已存到: {out_dir}")        # ============================================================# 同一個 feature，在不同距離下，normal vs 該 leak level 的差異有沒有穩定# ============================================================def plot_top_features_distance_effect_lines(    record_df,                           # record-level 特徵表    rank_df,                             # 特徵排名表，用來決定畫哪些特徵    target_levels=None,   # 要分析的 leak levels，預設 0, 30    top_n=20,                            # 只畫排名前幾名特徵    out_dir=None,                        # 輸出資料夾):    '''    同一個特徵，在不同距離下，Baseline vs Baseline+leak 的區分力有沒有穩定。    1.取前 top_n 個特徵    2.對每個特徵、每個 leak level、每個距離    3.計算 Baseline vs Baseline+leak 的 Cohen’s d    4.以距離為 x 軸、Cohen’s d 為 y 軸畫線    5.看這個特徵的區分力會不會因距離改變而失真    '''    # 檢查    if target_levels is None:        raise ValueError("請傳入 target_levels，例如 target_levels=tuple(ANALYSIS_LEVELS)")        # 先只保留指定 leak levels    df = record_df.copy()    df = df[df["leak_quantity"].isin(target_levels)].copy()    # 取前幾名特徵    top_features = rank_df.head(top_n)["feature"].tolist()    leak_levels = [lv for lv in target_levels if lv != 0]       # 把 baseline 以外的 leak levels 抽出來    distances = sorted(df["distance_cm"].dropna().unique())     # 取得所有距離    # 如果有指定輸出資料夾就先建立    if out_dir is not None:        out_dir = Path(out_dir)        out_dir.mkdir(parents=True, exist_ok=True)    # 逐個特徵處理    for feat in top_features:        rows = []                # 對每個 leak level、每個距離算 Cohen’s d        for lv in leak_levels:            for dist in distances:                sub = df[df["distance_cm"] == dist]                # 抽出 baseline 與 leak 的特徵值                x0 = sub.loc[sub["leak_quantity"] == 0, feat].dropna().values     # 在固定距離 dist 下：x0：Baseline 的這個特徵值                x1 = sub.loc[sub["leak_quantity"] == lv, feat].dropna().values    # 在固定距離 dist 下：x1：Baseline+lv 的這個特徵值                # 樣本太少就跳過                if len(x0) < 2 or len(x1) < 2:                    continue                                # 計算 Cohen’s d:在固定距離下，這個特徵對 Baseline vs Baseline+lv 的分離強度                d = _cohen_d(x1, x0)                                # 儲存結果                rows.append({                    "feature": feat,                    "distance_cm": dist,                    "leak_quantity": lv,                    "cohen_d": d,                    "abs_cohen_d": abs(d),                })        # 組合特徵表        plot_df = pd.DataFrame(rows)        if plot_df.empty:      # 如果沒有任何有效資料，就跳過這個特徵            continue        # 建立畫布        plt.figure(figsize=(8, 5), dpi=160)        # 每個 leak level 畫一條線        for lv, sub in plot_df.groupby("leak_quantity"):            sub = sub.sort_values("distance_cm")            plt.plot(                sub["distance_cm"],                sub["cohen_d"],                marker="o",                linewidth=1.8,                label=f"Baseline vs Baseline+{int(lv)}"            )        # 畫一條 y=0 基準線        plt.axhline(0.0, color="gray", linestyle="--", linewidth=1)        plt.title(f"{feat} - fixed distance normal vs leak effect")        plt.xlabel("Distance (cm)")        plt.ylabel("Cohen's d")        plt.legend()        plt.grid(True, alpha=0.25)        plt.tight_layout()        if out_dir is not None:            plt.savefig(out_dir / f"{feat}_distance_effect_lines.png", bbox_inches="tight")            plt.close()        else:            plt.show()    if out_dir is not None:        print(f"✅ 固定距離 effect line plots 已存到: {out_dir}")              # ============================================================# record-level PCA:每個 record 壓成 2 維後畫散點圖# ============================================================def plot_record_level_pca(    record_df,    record_id_col="record_id",    decision_col="decision",    out_path=None,    annotate_top_n=10,    show_review_labels=True,    random_state=42,          # 由呼叫端傳入 RANDOM_STATE):    """    1.每個 record 是一個點    2.用很多數值特徵做 PCA    3.降到 2 維後畫在平面上    4.依照 decision 上色，並特別把 review 點框起來    """    df = record_df.copy()    # 選出所有數值欄位,排除幾個不想拿來做 PCA 的欄位["label", "leak_quantity", "distance_cm", "pressure", "soft_score"]    feature_cols = [        c for c in df.columns        if pd.api.types.is_numeric_dtype(df[c])        and c not in {"label", "leak_quantity", "distance_cm", "pressure", "soft_score"}    ]    X = df[feature_cols].replace([np.inf, -np.inf], np.nan).dropna()    # 把 inf 轉成 nan,再把有缺值的列刪掉    df = df.loc[X.index].reset_index(drop=True)                         # 確保 df 和特徵矩陣 X 保持同樣列數    X = X.reset_index(drop=True)    X_scaled = StandardScaler().fit_transform(X.values)                 # 標準化，避免某些特徵尺度太大主導 PCA    pcs = PCA(n_components=2, random_state=random_state).fit_transform(X_scaled)    plot_df = df.copy()    plot_df["pc1"] = pcs[:, 0]    plot_df["pc2"] = pcs[:, 1]    plot_df["pc_radius"] = np.sqrt(plot_df["pc1"]**2 + plot_df["pc2"]**2)    # 計算每個點離原點的距離,用來找「最極端」的 review 點        # 依照 decision_col 畫三類點    color_map = {        "keep": "steelblue",        "review": "tomato",        "remove": "gray",    }    plt.figure(figsize=(11, 8), dpi=160)    values = [v for v in ["keep", "review", "remove"] if v in plot_df[decision_col].dropna().unique()]    for v in values:        sub = plot_df[plot_df[decision_col] == v]        plt.scatter(            sub["pc1"], sub["pc2"],            s=52,            alpha=0.78,            color=color_map.get(v, "gray"),            label=v,        )    # review 用黑框標    review_sub = plot_df[plot_df[decision_col] == "review"]    if len(review_sub) > 0:        plt.scatter(            review_sub["pc1"], review_sub["pc2"],            s=95, facecolors="none", edgecolors="black",            linewidths=1.0, label="review-outline",            )        # 只標最極端的幾個        if show_review_labels:            review_top = review_sub.sort_values("pc_radius", ascending=False).head(annotate_top_n)            for _, row in review_top.iterrows():                plt.annotate(                    str(row[record_id_col])[-18:],                    (row["pc1"], row["pc2"]),                    fontsize=7, alpha=0.85                )    plt.title("Record-level PCA")    plt.xlabel("PC1")    plt.ylabel("PC2")    plt.legend(loc="best", fontsize=8)    plt.tight_layout()    if out_path is not None:        out_path = Path(out_path)        out_path.parent.mkdir(parents=True, exist_ok=True)        plt.savefig(out_path, bbox_inches="tight")        plt.close()    else:        plt.show()    return plot_df# ============================================================#  每個 group 各輸出兩種圖# ============================================================def plot_groupwise_qc_views(        report_df,           # 完整資料表        feature_cols=None,   # 想看的特徵欄位        out_dir=None,        # 輸出資料夾        max_groups=None,     # 最多畫幾個 group    ):    """    每個 group 各輸出兩種圖：    1. robust z-score heatmap：這個 group 裡每筆 record 在「標準化後」是否異常    2. 原始特徵 boxplot + scatter points：在「原始特徵值」上實際落在哪裡    """    df = report_df.copy()    # 沒有指定 feature_cols，就用預設    if feature_cols is None:        feature_cols = ["log_rms_gap", "log_peak_gap", "log_peak_ratio", "b_all_5_70k_log_gap",]    # 保留真的存在於資料表的欄位    valid_feature_cols = [c for c in feature_cols if c in df.columns]    z_cols = [f"{c}_robust_z" for c in valid_feature_cols if f"{c}_robust_z" in df.columns]     # 找對應的 robust z-score 欄位    # 建立輸出資料夾,如果有指定 out_dir，就先建立資料夾    if out_dir is not None:        out_dir = Path(out_dir)        out_dir.mkdir(parents=True, exist_ok=True)            # 決定 group 的繪圖順序    group_order = (        df.groupby("group")["soft_score"]    # 先依 group 分組        .sum()                               # 對每組的 soft_score 加總        .sort_values(ascending=False)        # 依照總分由大到小排序        .index        .tolist()    )    # 如果有 max_groups，只取前幾個 group    if max_groups is not None:        group_order = group_order[:max_groups]            # 顏色設定    color_map = {"keep": "steelblue", "review": "tomato", "remove": "gray"}    # 逐 group 處理    for group_name in group_order:        gdf = df[df["group"] == group_name].copy().reset_index(drop=True)    # 先把該 group 的資料取出, 如果這組沒資料就跳過        if len(gdf) == 0:            continue                # 如果有 decision 欄位，就建立排序用欄位 _decision_rank        if "decision" in gdf.columns:            decision_rank = {"review": 0, "remove": 1, "keep": 2}            gdf["_decision_rank"] = gdf["decision"].map(decision_rank).fillna(9)        else:            gdf["_decision_rank"] = 9        # 計算 max_abs_z,如果 gdf 還沒有 max_abs_z 欄位，就自己算 -> 這個值可以視為「這筆資料最異常的程度」        if "max_abs_z" not in gdf.columns:            gdf["max_abs_z"] = gdf[z_cols].abs().max(axis=1) if len(z_cols) > 0 else 0.0        # 排序 group 內 record,排序規則是：先看 decision(review 最前面) -> 再看 soft_score(分數高的在前) -> 再看 max_abs_z(越異常的在前)        gdf = gdf.sort_values(            by=["_decision_rank", "soft_score", "max_abs_z"],            ascending=[True, False, False]        ).reset_index(drop=True)        # 整理檔名        stem = re.sub(r"[^a-zA-Z0-9_-]+", "_", str(group_name))        # -- 圖1:heatmap        #    只有在 z_cols 不為空時才畫        if len(z_cols) > 0:            heat_values = gdf[z_cols].values     # 取出 heatmap 數值            fig, ax = plt.subplots(figsize=(8, max(6, 0.32 * len(gdf))), dpi=160)            im = ax.imshow(heat_values, aspect="auto", cmap="coolwarm", vmin=-4, vmax=4)    # 畫矩陣熱圖            ax.set_title(f"{group_name} - robust z-score heatmap")   # X軸：把欄名顯示成原始特徵名，不顯示 _robust_z 後綴            ax.set_xticks(np.arange(len(z_cols)))            ax.set_xticklabels([c.replace("_robust_z", "") for c in z_cols], rotation=45, ha="right")            # y軸：record_id 最後 18 個字 + decision            y_labels = [                f"{str(row['record_id'])[-18:]} | {row['decision']}"                for _, row in gdf.iterrows()            ]            ax.set_yticks(np.arange(len(y_labels)))            ax.set_yticklabels(y_labels, fontsize=8)            cbar = plt.colorbar(im, ax=ax)            cbar.set_label("robust z-score")            plt.tight_layout()            if out_dir is not None:                plt.savefig(out_dir / f"{stem}_heatmap.png", bbox_inches="tight")                plt.close(fig)            else:                plt.show()        # -- 圖2:boxplot + points        n = len(valid_feature_cols)    # 有幾個特徵就畫幾個子圖        if n > 0:            fig, axes = plt.subplots(1, n, figsize=(4.8 * n, 4.8), dpi=160)            if n == 1:                axes = [axes]            for ax, col in zip(axes, valid_feature_cols):                vals = gdf[col].dropna().values                if len(vals) == 0:                    ax.set_title(col)                    continue                # A) 畫 boxplot                ax.boxplot(vals, positions=[0], widths=0.35, patch_artist=True,                           boxprops=dict(facecolor="lightgray", alpha=0.6))                #   所有點本來都會落在 x=0，會重疊，所以加入一點左右隨機偏移                x_jitter = np.random.uniform(-0.10, 0.10, size=len(gdf))                #   一筆一筆畫 scatter(review 點更大, 不透明度更高, 有黑色外框)                for i, (_, row) in enumerate(gdf.iterrows()):                    is_review = row.get("decision") == "review"                    ax.scatter(                        x_jitter[i], row[col],                        s=60 if is_review else 34,                        color=color_map.get(row.get("decision", "keep"), "gray"),                        alpha=0.95 if is_review else 0.45,                        edgecolors="black" if is_review else "none",                        linewidths=0.8 if is_review else 0.0,                        marker="o"                    )                ax.set_title(col)                ax.set_xticks([0])                ax.set_xticklabels([group_name], rotation=20)                ax.grid(True, alpha=0.25, axis="y")            plt.suptitle(f"{group_name} - group-wise QC features")            plt.tight_layout()            if out_dir is not None:                plt.savefig(out_dir / f"{stem}_boxplot.png", bbox_inches="tight")                plt.close(fig)            else:                plt.show()# ============================================================# 畫 group-level median heatmap(group 層級的特徵摘要)# ============================================================def plot_group_feature_summary_heatmap(    group_feature_summary,    feature_cols=None,    group_col="group",    out_path=None,    sort_by=None,):    """    每一列 = 一個 group    每一欄 = 這個 group 某個特徵的代表值（這裡假設是 median）    顏色 = 這個 group 在該特徵上，相對其他 groups 偏高還是偏低    -> 「哪些 group 在哪些特徵上，整體表現明顯偏離其他 group？」    """    df = group_feature_summary.copy()    # 決定要畫哪些特徵,如果沒有指定 feature_cols，就用預設    if feature_cols is None:        feature_cols = [            "log_rms_gap",            "log_peak_gap",            "log_peak_ratio",            "b_all_5_70k_log_gap",        ]            # 只保留 DataFrame 裡真的存在的欄位    feature_cols = [c for c in feature_cols if c in df.columns]    if len(feature_cols) == 0:        print("⚠️ group-level heatmap 沒有可用特徵")        return None    # 如果要指定排序欄位，就先排(如果你指定了 sort_by，而且該欄位存在,就依那個欄位由大到小排序,否則就照 group 名稱排序)    if sort_by is not None and sort_by in df.columns:        df = df.sort_values(sort_by, ascending=False).reset_index(drop=True)    else:        df = df.sort_values(group_col).reset_index(drop=True)    # 針對每個特徵，跨 group 做 robust z-score    heat_df = df[[group_col] + feature_cols].copy()    # 對每個特徵做跨-group robust z-score    for col in feature_cols:        med = heat_df[col].median()                    # 先算這個特徵在所有 groups 之間的中位數        mad = _mad(heat_df[col].values)                # 此特徵在各 group 間的穩健離散程度        scale = max(1.4826 * mad, 1e-6)                # 把 MAD 轉成穩健尺度，並避免分母為 0        heat_df[col] = (heat_df[col] - med) / scale    # 得到跨-group 的 robust z-score    # 畫 heatmap(圖的大小會根據：特徵數量,group 數量自動調整。)    plt.figure(figsize=(1.4 * len(feature_cols) + 3, 0.55 * len(heat_df) + 2), dpi=160)    # 把數值矩陣畫成熱圖    im = plt.imshow(        heat_df[feature_cols].values,        aspect="auto",        cmap="coolwarm",    # 藍色方向通常代表偏低,紅色方向通常代表偏高        vmin=-4,        vmax=4,    )    plt.title("Group-level Median Heatmap")        # x 軸：顯示每個特徵名稱，並旋轉 45 度避免重疊    plt.xticks(        ticks=np.arange(len(feature_cols)),        labels=feature_cols,        rotation=45,        ha="right"    )        # y軸：顯示每個 group 名稱    plt.yticks(        ticks=np.arange(len(heat_df)),        labels=heat_df[group_col].tolist()    )    cbar = plt.colorbar(im)    cbar.set_label("robust z-score across groups")    plt.tight_layout()    if out_path is not None:        out_path = Path(out_path)        out_path.parent.mkdir(parents=True, exist_ok=True)        plt.savefig(out_path, bbox_inches="tight")        plt.close()        print(f"✅ group-level median heatmap 已儲存: {out_path}")    else:        plt.show()    return heat_df# ============================================================# 畫 near/far 頻譜差異的 group-level median heatmap# ============================================================def plot_group_near_far_spectral_heatmap(        spectral_report_df,        feature_cols=None,        out_path=None,        sort_by="distance_cm",    ):    """    1.先把每個 group 的 near/far 頻譜差異特徵取 median    2.再把這些 group-level median 轉成「跨 group 的 robust z-score」    3.最後畫成 heatmap，看哪個 group 在哪些頻譜差異特徵上特別高或特別低    """    df = spectral_report_df.copy()    # 如果沒指定 feature_cols，就用預設這些 near/far 特徵    if feature_cols is None:        feature_cols = [            "psd_log_corr",            "psd_log_cosine_sim",            "psd_js_div",            "psd_log_l1_gap",            "log_rms_ratio",            "b_all_5_70k_log_ratio",            "b3_20_70k_log_ratio",            "b5_120_70k_log_ratio",        ]    # 只保留實際存在的欄位    feature_cols = [c for c in feature_cols if c in df.columns]    if len(feature_cols) == 0:        print("⚠️ 沒有可畫的 near/far spectral 特徵")        return None        # group-level 聚合:準備 groupby("group") 後每欄怎麼聚合    agg_dict = {"label": "median", "leak_quantity": "median", "distance_cm": "median", "pressure": "median"}    for c in feature_cols:        agg_dict[c] = "median"    # 每個 group 都會算出：label, leak_quantity, distance_cm, pressure, 每個 near/far feature 的 median    # 「每列一個 group」的摘要表    gdf = df.groupby("group", as_index=False).agg(agg_dict)    # 排序：如果 sort_by 欄位存在，就照那欄排序，預設是 distance_cm, 否則就照 group 名稱排序    if sort_by in gdf.columns:        gdf = gdf.sort_values(sort_by).reset_index(drop=True)    else:        gdf = gdf.sort_values("group").reset_index(drop=True)    # 建立 heatmap 資料    heat_df = gdf[["group"] + feature_cols].copy()        # 跨 group 做 robust z-score    for col in feature_cols:        med = heat_df[col].median()                    # 算所有 groups 的中位數 med        mad = _mad(heat_df[col].values)                # 算跨 group 的 MAD mad        scale = max(1.4826 * mad, 1e-6)                # 用 1.4826 * mad 當穩健尺度        heat_df[col] = (heat_df[col] - med) / scale    # 再把每個 group 的值轉成 robust z-score    # 畫 heatmap(x 軸是特徵名，y 軸是 group 名稱)    plt.figure(figsize=(1.5 * len(feature_cols) + 3, 0.55 * len(heat_df) + 2), dpi=160)    im = plt.imshow(heat_df[feature_cols].values, aspect="auto", cmap="coolwarm", vmin=-4, vmax=4)    plt.title("Near/Far Spectral Difference Heatmap")    plt.xticks(np.arange(len(feature_cols)), feature_cols, rotation=45, ha="right")    plt.yticks(np.arange(len(heat_df)), heat_df["group"].tolist())    cbar = plt.colorbar(im)    cbar.set_label("robust z-score across groups")    plt.tight_layout()    if out_path is not None:        out_path = Path(out_path)        out_path.parent.mkdir(parents=True, exist_ok=True)        plt.savefig(out_path, bbox_inches="tight")        plt.close()        print(f"✅ near/far spectral heatmap 已儲存: {out_path}")    else:        plt.show()    return gdf, heat_df# ============================================================# 每個 group 各畫：ai0(far) vs ai1(near) 的平均 PSD + log(Pxx_near / Pxx_far)# ============================================================def plot_group_near_far_psd(    records,    out_dir,    use_pressure=False,    nperseg=NPERSEG,    smooth_sigma=1.0,    max_groups=None,):    """    把資料先依 group 分組，然後對每個 group 各畫一張圖，比較 ai0(far) 和 ai1(near) 的平均 PSD，並畫出 log(Pxx_near / Pxx_far)    1.同一組條件下，far 跟 near 的頻譜長什麼樣    2.哪些頻率是 near 比 far 強，或反過來    """    from scipy.ndimage import gaussian_filter1d    # 先建立輸出資料夾與基本設定    out_dir = Path(out_dir)    out_dir.mkdir(parents=True, exist_ok=True)    eps = 1e-12    # 先把 records 按 group 分類    group_map = {}    for r in records:        group_name = make_group_name(r["meta"], use_pressure=use_pressure)    # 每筆 record 用 make_group_name(...) 算出它屬於哪個 group        group_map.setdefault(group_name, []).append(r)    items = sorted(group_map.items())    if max_groups is not None:        items = items[:max_groups]    # 逐 group 處理    for group_name, group_records in items:        # 每次處理一個 group，並初始化        psd_ai0_list = []    # 存每筆 far 的 PSD        psd_ai1_list = []    # 存每筆 near 的 PSD        f_ref = None         # 記住頻率軸        # 對 group 內每筆 record 算 PSD        for r in group_records:                ai0 = np.asarray(r["signal"]["ai0"], dtype=float)            ai1 = np.asarray(r["signal"]["ai1"], dtype=float)            fs = float(r["fs"])            # 分別對：far, near 算 PSD,並保留原始 PSD 尺度(normalize=False)            f0, P0 = compute_psd(ai0, fs, nperseg=nperseg, normalize=False, smooth_sigma=0)            f1, P1 = compute_psd(ai1, fs, nperseg=nperseg, normalize=False, smooth_sigma=0)            # 對齊長度與頻率範圍            n = min(len(P0), len(P1))            f = f0[:n]            P0 = P0[:n]            P1 = P1[:n]            # 把太低頻的部分去掉，只保留 FREQ_MIN 以上的頻率            mask = f >= FREQ_MIN            f = f[mask]            P0 = P0[mask]            P1 = P1[mask]                        # 把每筆 record 的 PSD 收集起來            psd_ai0_list.append(P0)            psd_ai1_list.append(P1)            f_ref = f        # 如果這個 group 沒資料就跳過        if len(psd_ai0_list) == 0:            continue                # 計算 group 的幾何平均 PSD        mean_psd_ai0 = np.exp(np.mean(np.log(np.array(psd_ai0_list) + eps), axis=0))        mean_psd_ai1 = np.exp(np.mean(np.log(np.array(psd_ai1_list) + eps), axis=0))        log_ratio = np.log((mean_psd_ai1 + eps) / (mean_psd_ai0 + eps))     # 計算 near/far 的 log ratio        # 可選的平滑(如果 smooth_sigma > 0，就用 Gaussian filter 平滑曲線)        if smooth_sigma and smooth_sigma > 0:            mean_psd_ai0 = gaussian_filter1d(mean_psd_ai0, sigma=smooth_sigma)            mean_psd_ai1 = gaussian_filter1d(mean_psd_ai1, sigma=smooth_sigma)            log_ratio = gaussian_filter1d(log_ratio, sigma=smooth_sigma)                # 畫兩張子圖        fig, axes = plt.subplots(2, 1, figsize=(12, 8), dpi=160, sharex=True)        # 上圖：平均 PSD 比較(near / far 的整體頻譜形狀,哪些頻率能量比較高)        axes[0].semilogy(f_ref, mean_psd_ai0, color="steelblue", label="ai0 = far", linewidth=1.5)        axes[0].semilogy(f_ref, mean_psd_ai1, color="tomato", label="ai1 = near", linewidth=1.5)        axes[0].set_title(f"{group_name} - Mean PSD")        axes[0].set_ylabel("PSD")        axes[0].legend()        axes[0].grid(True, alpha=0.25)        # 下圖：log ratio(near 相對 far 的差異,灰色虛線 y=0 是基準線)        axes[1].plot(f_ref, log_ratio, color="purple", linewidth=1.3)        axes[1].axhline(0.0, color="gray", linestyle="--", linewidth=1)        axes[1].set_title("log(Pxx_near / Pxx_far)")        axes[1].set_xlabel("Frequency (Hz)")        axes[1].set_ylabel("Log Ratio")        axes[1].grid(True, alpha=0.25)        plt.tight_layout()        stem = re.sub(r"[^a-zA-Z0-9_-]+", "_", str(group_name))        plt.savefig(out_dir / f"{stem}_near_far_psd.png", bbox_inches="tight")        plt.close(fig)    print(f"✅ 每個 group 的 near/far PSD 比較圖已存到: {out_dir}")# ============================================================# 每個 group 各畫一張 band energy 比較圖# ============================================================def plot_group_near_far_band_bars(    records,    bands,    out_dir,    use_pressure=False,):    """    1.每個 group 各畫一張圖    2.比較 far(ai0) 和 near(ai1) 在各個 band 的能量大小    3.同時看 log(E_near / E_far)，確認哪個 band 是 near 明顯較強或較弱    """    # 建立輸出資料夾與基本參數    out_dir = Path(out_dir)    out_dir.mkdir(parents=True, exist_ok=True)    eps = 1e-12        # 先把 records 依 group 分類    group_map = {}    for r in records:        group_name = make_group_name(r["meta"], use_pressure=use_pressure)     # 每筆 record 用 make_group_name(...) 決定所屬 group        group_map.setdefault(group_name, []).append(r)            # 逐 group 處理    for group_name, group_records in sorted(group_map.items()):        rows = []    # rows 是用來收集這個 group 內每筆 record 的 band 特徵        # 對 group 內每筆 record 算各 band energy        for r in group_records:            ai0 = np.asarray(r["signal"]["ai0"], dtype=float)            ai1 = np.asarray(r["signal"]["ai1"], dtype=float)            fs = float(r["fs"])                        # 先建立一列資料            row = {"record_id": r["record_id"]}            for band in bands:                e0 = compute_band_energy(ai0, fs, band)     # far 在這個 band 的能量                e1 = compute_band_energy(ai1, fs, band)     # near 在這個 band 的能量                row[f"{band['name']}_e0"] = e0                row[f"{band['name']}_e1"] = e1                row[f"{band['name']}_log_ratio"] = np.log((e1 + eps) / (e0 + eps))            rows.append(row)        if len(rows) == 0:            continue        # 把 group 內所有 record 組成 DataFrame:每列 -> 一筆 record , 每欄 -> 某個 band 的 far/near energy 或 log ratio        df_band = pd.DataFrame(rows)        # 對每個 band 取 group median        band_names = [b["name"] for b in bands]        med_e0 = [df_band[f"{name}_e0"].median() for name in band_names]         # 每個 band 的 far median energy        med_e1 = [df_band[f"{name}_e1"].median() for name in band_names]         # 每個 band 的 near median energy        med_lr = [df_band[f"{name}_log_ratio"].median() for name in band_names]  # 每個 band 的 median log ratio        # 建立 x 軸位置, x 是每個 band 在 x 軸上的位置        x = np.arange(len(band_names))        width = 0.36        # 畫兩張子圖        fig, axes = plt.subplots(2, 1, figsize=(12, 8), dpi=160, sharex=True)        # 上圖：far vs near 的 median band energy -> 在哪些 band，near 的能量比 far 高,差距大不大        axes[0].bar(x - width / 2, med_e0, width=width, color="steelblue", label="ai0 = far")        axes[0].bar(x + width / 2, med_e1, width=width, color="tomato", label="ai1 = near")        axes[0].set_title(f"{group_name} - Median Band Energy")        axes[0].set_ylabel("Energy")        axes[0].legend()        axes[0].grid(True, alpha=0.25, axis="y")        # 下圖：median log(E_near / E_far) -> 快速判斷 band 差異方向        axes[1].bar(x, med_lr, width=0.55, color="purple", alpha=0.85)        axes[1].axhline(0.0, color="gray", linestyle="--", linewidth=1)        axes[1].set_title("Median log(E_near / E_far)")        axes[1].set_ylabel("Log Ratio")        axes[1].set_xticks(x)        axes[1].set_xticklabels(band_names, rotation=30, ha="right")        axes[1].grid(True, alpha=0.25, axis="y")        plt.tight_layout()        stem = re.sub(r"[^a-zA-Z0-9_-]+", "_", str(group_name))        plt.savefig(out_dir / f"{stem}_band_energy.png", bbox_inches="tight")        plt.close(fig)    print(f"✅ 每個 group 的 band energy 比較圖已存到: {out_dir}")# ============================================================# 畫多個特徵的熱圖 selected features vs (leak_quantity, distance_cm) heatmap# ============================================================def plot_selected_feature_heatmap_by_condition(        record_df,        selected_features,        out_path=None,        label_filter=1,    ):    """    列 = feature    欄 = leak_quantity × distance_cm    值 = record-level median，並做 feature-wise robust z-score    """    df = record_df.copy()    # 如果有指定 label_filter，就只保留某個類別    if label_filter is not None:        df = df[df["label"] == label_filter].copy()    # 從你給的 selected_features 裡，挑出實際存在於 dataframe 欄位中的特徵    use_features = [c for c in selected_features if c in df.columns]    if len(use_features) == 0:    # 如果一個可用特徵都沒有，就直接結束        print("⚠️ 沒有可畫的 selected features")        return None, None    # 依照 leak_quantity 和 distance_cm 分組 -> 每組對所有指定 feature 算中位數 -> 產生一張整理過的表    cond_df = (        df.groupby(["leak_quantity", "distance_cm"])[use_features]        .median()        .sort_index()    )    if cond_df.empty:        print("⚠️ 沒有資料可畫 selected feature heatmap")        return None, None    heat_df = cond_df.T.copy()    # 表格轉置    # feature-wise robust z-score：每個 feature 自己做標準化    for feat in heat_df.index:        vals = heat_df.loc[feat].values.astype(float)        med = np.median(vals)        mad = np.median(np.abs(vals - med))        scale = max(1.4826 * mad, 1e-6)        heat_df.loc[feat] = (vals - med) / scale    # 幫每個欄位做顯示標籤    col_labels = [        f"{'Baseline' if int(lq) == 0 else f'Baseline+{int(lq)}'}\n{int(dist)}cm"        for lq, dist in heat_df.columns    ]    plt.figure(        figsize=(max(10, 0.85 * len(col_labels)), max(10, 0.26 * len(use_features))),        dpi=180    )    im = plt.imshow(        heat_df.values,        aspect="auto",        cmap="coolwarm",        vmin=-4,        vmax=4,    )    plt.xticks(np.arange(len(col_labels)), col_labels, rotation=45, ha="right")    plt.yticks(np.arange(len(use_features)), use_features)    plt.title("Selected Features vs Leak Quantity / Distance (dev, record-level)")    plt.xlabel("Condition")    plt.ylabel("Feature")    cbar = plt.colorbar(im)    cbar.set_label("Feature-wise robust z-score")    plt.tight_layout()    if out_path is not None:        out_path = Path(out_path)        out_path.parent.mkdir(parents=True, exist_ok=True)        plt.savefig(out_path, bbox_inches="tight")        plt.close()        print(f"✅ 已儲存: {out_path}")    else:        plt.show()    return cond_df, heat_df# ============================================================# 正常 vs 洩漏的特徵狀態，並產生cohen's d# ============================================================def compare_normal_vs_leak_features(features_df, top_n=10, save_path=None):    """    對比正常 vs 洩漏的特徵分布 (根據leak_label分組)    找出那些特徵最能區分[正常訊號 vs 洩漏訊號]，並用圖表展示    適合用來做整體特徵區分性分析和可視化統計對比        1️⃣ 計算每個特徵的區分能力    2️⃣ 挑出 top N    3️⃣ 畫箱型圖比較分布       Parameters    ----------    features_df 包含所有特徵和 'leak_label' 的資料 : DataFrame            top_n 顯示前 N 個最有區分性的特徵 : int            save_path 圖片儲存路徑: str or None            """        print("\n" + "=" * 60)    print("對比正常 vs 洩漏特徵分布")    print("=" * 60)        # 分離正常和洩漏樣本    normal = features_df[features_df['label'] == 0]    leak = features_df[features_df['label'] == 1]        print(f"正常樣本: {len(normal)} 筆")    print(f"洩漏樣本: {len(leak)} 筆")        # 選擇數值特徵，排除metadata特徵    exclude_cols = ['distance', 'pressure', 'leak_quantity', 'record_id', 'label', 'window_idx', "t_start", "label"]    numeric_features = features_df.select_dtypes(include=[np.number]).columns    feature_cols = [c for c in numeric_features if c not in exclude_cols]        # 計算區分度    separability = []    for feat in feature_cols:        try:            # 計算兩群的平均            mean_normal = normal[feat].mean()    # 正常訊號的平均值            mean_leak = leak[feat].mean()    # 洩漏訊號的平均值            std_pooled = np.sqrt((normal[feat].std()**2 + leak[feat].std()**2) / 2)     # 合併標準差                        # 計算Cohen's d:數值越高代表該特徵具有越高的區分力            if std_pooled > 0:                cohen_d = abs(mean_leak - mean_normal) / std_pooled                separability.append({                    'feature': feat,                    'cohen_d': cohen_d,                    'mean_normal': mean_normal,                    'mean_leak': mean_leak                })        except:            continue        # 尋找Top特徵    sep_df = pd.DataFrame(separability).sort_values('cohen_d', ascending=False)    top_features = sep_df.head(top_n)['feature'].tolist()        print(f"\n前 {top_n} 個最具區分性的特徵:")    print(sep_df.head(top_n)[['feature', 'cohen_d']].to_string(index=False))        # 繪製箱型圖    n_cols = 4    n_rows = (top_n + n_cols - 1) // n_cols        fig, axes = plt.subplots(n_rows, n_cols, figsize=(16, n_rows * 3))    axes = axes.flatten() if n_rows > 1 else [axes]        # 逐一畫每個重要的特徵    for idx, feat in enumerate(top_features):        if idx >= len(axes):            break                    ax = axes[idx]        data_to_plot = [normal[feat].dropna(), leak[feat].dropna()]                # 畫箱型圖，patch_artist=True → 才能填顏色        bp = ax.boxplot(data_to_plot, labels=['正常', '洩漏'], patch_artist=True)        bp['boxes'][0].set_facecolor('lightblue')        bp['boxes'][1].set_facecolor('lightcoral')                ax.set_title(f'{feat}\n(Cohen\'s d = {sep_df[sep_df["feature"]==feat]["cohen_d"].values[0]:.2f})',                    fontsize=9)        ax.set_ylabel('特徵值')        ax.grid(True, alpha=0.3, axis='y')        for idx in range(len(top_features), len(axes)):        axes[idx].axis('off')        plt.suptitle('正常 vs 洩漏 - 特徵分布對比', fontsize=14, fontweight='bold')    plt.tight_layout()        if save_path:        Path(save_path).parent.mkdir(parents=True, exist_ok=True)        plt.savefig(save_path, dpi=150, bbox_inches='tight')        print(f"\n✅ 對比圖已儲存: {save_path}")        plt.close(fig)        # 將計算好的Cohen's d的分數存成字典傳出，方便後續計算共線性使用    cohen_dict = dict(zip(sep_df.feature, sep_df.cohen_d))        return fig, sep_df, cohen_dict# ============================================================# 主程式入口# ============================================================def plot_all_features_pairwise_boxplots(        record_df,    # record-level 特徵表        level_a,      # 第一組，例如 0        level_b,      # 第二組，例如 30        out_dir,      # 儲存圖的路徑        level_col="leak_quantity",    # 用哪個欄位分組，預設用洩漏量        features_per_page=12,     # 每頁畫幾個特徵        prefix=None,     # 輸出檔名前綴        label_a=None,    # 圖上顯示的組名        label_b=None,    ):    '''    把兩組資料的所有 record-level 特徵，一頁一頁畫成箱型圖，並先用 Cohen's d 幫特徵排序    '''    # 把輸出路徑轉成 Path，並建立資料夾    out_dir = Path(out_dir)    out_dir.mkdir(parents=True, exist_ok=True)    # 只保留你要比較的兩組資料，例如只留 0 和 30    df = record_df[record_df[level_col].isin([level_a, level_b])].copy()    # 這裡列出哪些欄位不是特徵，不要拿來畫箱型圖    exclude_cols = {        "filename", "record_id", "label",        "leak_quantity", "distance_cm", "pressure",        "condition", "group",        "decision", "soft_score", "ratio_warning",        "ratio_reason", "reason", "family_reason"    }    # 自動找出真正要分析的特徵欄(必須是數值型, 不能在排除清單裡)    feature_cols = [        c for c in df.columns        if pd.api.types.is_numeric_dtype(df[c]) and c not in exclude_cols    ]    # 準備一個空 list，等等存每個特徵的排序分數    rows = []    # 逐個特徵處理    for feat in feature_cols:        # 把這個特徵拆成兩組：x0：第一組, x1：第二組        x0 = df.loc[df[level_col] == level_a, feat].dropna().values        x1 = df.loc[df[level_col] == level_b, feat].dropna().values                # 如果其中一組樣本太少，就跳過，不畫        if len(x0) < 2 or len(x1) < 2:            continue        # 計算 Cohen's d        s0 = np.std(x0, ddof=1)    # 先算兩組標準差        s1 = np.std(x1, ddof=1)        pooled = np.sqrt((s0**2 + s1**2) / 2.0)    # 再算 pooled std        d = 0.0 if pooled < 1e-12 else (np.mean(x1) - np.mean(x0)) / pooled     # 最後算效果量, d 越大，表示兩組差異越明顯        rows.append({            "feature": feat,            "cohen_d": d,            "abs_cohen_d": abs(d),        })    # 把所有特徵整理成表，並依照 abs_cohen_d 由大到小排序    rank_df = pd.DataFrame(rows).sort_values("abs_cohen_d", ascending=False).reset_index(drop=True)    # 如果最後沒有任何可畫特徵，就提示並結束    if rank_df.empty:        print(f"⚠️ {level_a} vs {level_b} 沒有可畫特徵")        return None        # 如果你沒有自己指定檔名前綴，就自動產生。    if prefix is None:        prefix = f"boxplot_{int(level_a)}_vs_{int(level_b)}"            # 先把排序結果輸出成 CSV    rank_df.to_csv(out_dir / f"{prefix}_ranking.csv", index=False, encoding="utf-8-sig")    ranked_features = rank_df["feature"].tolist()     # 排序後的特徵清單    n_pages = int(np.ceil(len(ranked_features) / features_per_page))     # 總共要畫幾頁    # 如果你沒手動指定圖上的組名，就自動命名    if label_a is None:        label_a = "Baseline" if int(level_a) == 0 else f"Baseline+{int(level_a)}"    if label_b is None:        label_b = "Baseline" if int(level_b) == 0 else f"Baseline+{int(level_b)}"    # 開始逐頁畫圖    for page_idx in range(n_pages):        # 取出這一頁要畫的特徵        feats = ranked_features[page_idx * features_per_page:(page_idx + 1) * features_per_page]        # 建立這一頁的子圖。        # 每頁固定 4 欄 -> 列數依特徵數決定 -> flatten() 後方便逐格填圖        n_cols = 4        n_rows = int(np.ceil(len(feats) / n_cols))        fig, axes = plt.subplots(n_rows, n_cols, figsize=(16, n_rows * 3.2), dpi=160)        axes = np.atleast_1d(axes).flatten()                # 逐個子圖、逐個特徵開始畫        for ax, feat in zip(axes, feats):            # 再次取出這個特徵在兩組的資料            x0 = df.loc[df[level_col] == level_a, feat].dropna()            x1 = df.loc[df[level_col] == level_b, feat].dropna()            # 畫箱型圖            bp = ax.boxplot(                [x0, x1],                tick_labels=[label_a, label_b],    # x 軸兩組名稱                patch_artist=True,     # 讓盒子可以填色                showfliers=False       # 不顯示離群點            )            # 把兩組箱型圖染成不同顏色            bp["boxes"][0].set_facecolor("lightblue")            bp["boxes"][1].set_facecolor("lightcoral")            # 把這個特徵名和它的 Cohen's d 顯示在標題上            d_val = rank_df.loc[rank_df["feature"] == feat, "cohen_d"].values[0]            ax.set_title(f"{feat}\n(Cohen's d={d_val:.2f})", fontsize=9)            # 加上 y 軸淡淡的格線，方便看分布高低            ax.grid(True, alpha=0.3, axis="y")            _set_robust_ylim(ax, [x0, x1], lower_pct=2, upper_pct=98, pad_ratio=0.08)    # 自動調整 y 軸範圍                # 如果這一頁的格子比實際特徵數多，剩下空白格就關掉        for ax in axes[len(feats):]:            ax.axis("off")        plt.suptitle(f"{label_a} vs {label_b} (record-level)", fontsize=14, fontweight="bold")        plt.tight_layout()        plt.savefig(out_dir / f"{prefix}_page_{page_idx + 1:02d}.png", dpi=150, bbox_inches="tight")        plt.close(fig)    print(f"✅ {label_a} vs {label_b} 箱型圖已輸出，共 {n_pages} 頁")    return rank_df